def flag_of(iso):
    return ''.join(chr(0x1F1E6 + (ord(c) - 65)) for c in iso.upper())


def location_for_colo(colo):
    key = str(colo or '').strip().upper()
    hit = COLO_LOCATIONS.get(key)
    if hit:
        city, country, iso = hit
        return {'city': city, 'country': country, 'iso': iso, 'flag': flag_of(iso)}
    return {'city': key or 'Auto edge', 'country': 'Cloudflare edge', 'iso': '', 'flag': '🌐'}
